// AiXenix Cosmos Lab: observed metadata for the Universe map (content-owned).
//
// What is here: catalogued galaxies (31) and known stars (Sun, Galactic-centre anchor, bright naked-eye stars, stars within
// 5 pc, and the host stars of the catalogue scenes), each with its sources and per-field provenance. A larger Gaia DR3 sample
// (stars within about 25 pc) is a separate file, loaded on demand with loadGaiaOverlay().
// What is not here: the procedural galaxy model, star addresses and generated systems. Those are core's (web/src/cosmos).
//
// Frame: galactocentric, parsecs, astropy convention (R0 = 8122 pc, z_sun = 20.8 pc), the same rigid transform as core's
// icrsToGalactocentric. galactocentricPc values are precomputed from the observed ra/dec/distance and are 'reconstructed'.
//
// Data: generated by web/docs/cosmos/build_cosmos_data.py from primary-source snapshots (web/docs/cosmos/raw).

import type { Lang, LocalizedText } from './catalog';
import { tx } from './catalog';
import { COSMOS_DATA_META, COSMOS_GALAXIES, COSMOS_SOURCES, KNOWN_STARS } from './cosmos.generated';

export { COSMOS_DATA_META, COSMOS_GALAXIES, COSMOS_SOURCES, KNOWN_STARS };

export type Vec3 = [number, number, number];

/** observed = as published by a catalogue; reconstructed = derived here by a stated method; procedural = generated by the model. */
export type CosmosProvenance = 'observed' | 'reconstructed' | 'procedural';

export interface CosmosSource {
  id: string;
  title: string;
  url: string;
}

/**
 * A measured value with its uncertainty and what that uncertainty means:
 * - formal: the catalogue's formal error;
 * - propagated: derived from a formal error (for example a distance from parallax +- error);
 * - spread_of_published: the standard deviation of independent published values (NED-D), not a formal error;
 * - assumed_typical: no catalogue error; a typical uncertainty of the method is shown and labelled as assumed;
 * - none: no uncertainty available.
 */
export interface Measured {
  value: number;
  err?: number | null;
  errMinus?: number | null;
  errPlus?: number | null;
  errKind: 'formal' | 'propagated' | 'spread_of_published' | 'assumed_typical' | 'none';
  method?: string;
}

export type GalaxyKind = 'spiral' | 'barred_spiral' | 'lenticular' | 'elliptical' | 'dwarf_elliptical' | 'irregular' | 'dwarf_spheroidal';
export type GalaxyGroup = 'local_group' | 'milky_way_satellites' | 'm31_subgroup' | 'm81_group' | 'other';

/** A catalogued galaxy. Structurally a superset of core's GalaxyInput. */
export interface GalaxyInfo {
  id: string; // shared with core: milky_way, lmc, smc, m31, ...
  name: LocalizedText;
  altNames: string[];
  kind: GalaxyKind;
  kindLabel: LocalizedText;
  group: GalaxyGroup;
  groupLabel: LocalizedText;
  /** The galaxy it orbits, when it is a satellite (galaxy id). */
  host?: string;
  /** Conventional Hubble type, e.g. 'SA(s)b', 'dSph', 'IB(s)m'. */
  morphology: string;
  /** The catalogue's coded type (RC3), when the readable type came from it. */
  morphologyCode?: string | null;
  morphologySource?: string | null;
  /** ICRS position of the centre (degrees). The Milky Way: the direction of the Galactic centre. */
  raDeg: number;
  decDeg: number;
  /** Heliocentric distance (kpc). The Milky Way: the distance of its centre (R0). */
  distanceKpc: Measured;
  /** Centre in the shared galactocentric frame (pc). The Milky Way: [0, 0, 0]. */
  galactocentricPc: Vec3;
  majorAxisArcmin?: number;
  /** Isophotal major diameter converted at the adopted distance (kpc); the Milky Way: NASA's ~100,000 ly. */
  diameterKpc?: number;
  /** Apparent minor/major axis ratio. */
  axisRatio?: number;
  /** Inclination of the disc to the sky plane (deg; 90 = edge-on), from the axis ratio (UNGC). */
  inclinationDeg?: number;
  /** Position angle of the major axis on the sky (deg, north through east), RC3; absent = not catalogued. */
  positionAngleDeg?: number;
  /** Stellar mass (Msun): K-band luminosity with M/L = 1 (UNGC convention); the Milky Way: 5e10 (Bland-Hawthorn & Gerhard 2016). */
  stellarMassMsun?: number;
  bMag?: number;
  description: LocalizedText;
  /** What is approximate about the shape and orientation. */
  shapeNote: LocalizedText;
  /** Per field: observed or reconstructed. Keys: position, distance, diameterKpc, inclinationDeg, positionAngleDeg, stellarMassMsun, galactocentricPc. */
  fieldProvenance: Record<string, CosmosProvenance>;
  /** Source ids (COSMOS_SOURCES). */
  sources: string[];
}

export type StarCategory = 'sun' | 'bright' | 'nearby' | 'scene_host';

/** An observed star (or the Galactic-centre anchor). Structurally a superset of core's KnownStarInput. */
export interface KnownStar {
  id: string; // 'sun', 'sgr_a_star', 'hip_<n>', 'gaia_<source_id>', 'nexsci_<host>'
  name: LocalizedText;
  /** Catalogue designations: HIP, HR, HD, Bayer, Gaia DR3, archive host name. */
  designations: string[];
  iauName?: string;
  hip?: number;
  gaiaDr3?: string; // source_id as a string (exceeds 2^53)
  /** What the object is. Compact kinds come from the linked catalogue scene; a Gaia-only white dwarf is classified by colour and absolute magnitude (fieldProvenance.objectKind = 'reconstructed'). */
  objectKind: 'star' | 'white_dwarf' | 'neutron_star' | 'pulsar' | 'black_hole';
  /** Hipparcos proper motion (mas/yr), for Hipparcos stars. */
  pmRaMasYr?: number;
  pmDecMasYr?: number;
  /** Absent for the Sun (the frame anchor has no direction). */
  raDeg?: number;
  decDeg?: number;
  epoch?: string;
  parallaxMas?: Measured;
  /** Heliocentric distance (pc). null only for the Sun. */
  distancePc: Measured | null;
  /** good: relative parallax error < 10 %; uncertain: < 20 %; poor: larger (the distance is then only indicative). */
  distanceQuality: 'good' | 'uncertain' | 'poor' | null;
  /** In the shared galactocentric frame (pc); absent when there is no usable distance. */
  galactocentricPc?: Vec3;
  vMag?: number;
  gMag?: number;
  hipMag?: number;
  bvColor?: number;
  bpRp?: number;
  ruwe?: number;
  spectralType?: string;
  teffK?: number;
  massSun?: number;
  radiusSun?: number;
  luminositySun?: number;
  /** A catalogue scene (data/Scenes/<id>.json) for this star: its existing reconstruction, with that scene's own limits. */
  sceneId?: string;
  categories: StarCategory[];
  /** The star's catalogue record is observed. A scene or a generated planetary system attached to it keeps its own provenance. */
  provenance: 'observed';
  fieldProvenance: Record<string, CosmosProvenance>;
  sources: string[];
  note?: LocalizedText;
}

export interface CosmosDataMeta {
  schema: string;
  brand: string;
  generator: string;
  frame: { id: string; convention: string; r0Pc: number; zSunPc: number; sunPositionPc: Vec3; gcRaDeg: number; gcDecDeg: number; roll0Deg: number; sources: string[] };
  counts: { galaxies: number; galaxiesC1?: number; regions?: number; knownStars: number; gaiaOverlay: number };
  snapshots: Record<string, { retrieved_utc: string; sha256: string; url: string }>;
  files?: Record<string, string>;
}

// ---- lookups ------------------------------------------------------------------------------------------------------

const galaxyIndex = new Map(COSMOS_GALAXIES.map((g) => [g.id, g]));
const starIndex = new Map(KNOWN_STARS.map((s) => [s.id, s]));

export function galaxyById(id: string): GalaxyInfo | undefined {
  return galaxyIndex.get(id);
}

export function starById(id: string): KnownStar | undefined {
  return starIndex.get(id);
}

/** Known stars linked to a catalogue scene (several for binaries, e.g. Alpha Centauri). */
export function starsForScene(sceneId: string): KnownStar[] {
  return KNOWN_STARS.filter((s) => s.sceneId === sceneId);
}

/** Satellites of a galaxy (by `host`). */
export function satellitesOf(galaxyId: string): GalaxyInfo[] {
  return COSMOS_GALAXIES.filter((g) => g.host === galaxyId);
}

export function sourcesOf(ids: string[]): CosmosSource[] {
  return ids.map((id) => COSMOS_SOURCES[id]).filter((s): s is CosmosSource => !!s);
}

function fold(s: string): string {
  return s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/ё/g, 'е');
}

export interface CosmosHit {
  type: 'galaxy' | 'star';
  id: string;
  title: string;
  subtitle: string;
  score: number;
}

/** Search galaxies and known stars by name (both languages) and designation (HIP, HD, Bayer, Gaia DR3, M31...). */
export function searchCosmos(query: string, lang: Lang, limit = 30): CosmosHit[] {
  const words = fold(query.trim()).split(/\s+/).filter(Boolean);
  if (!words.length) return [];
  const score = (title: string, rest: string): number => {
    const t = fold(title);
    const r = fold(rest);
    let s = 0;
    for (const w of words) {
      if (t === w) s += 10;
      else if (t.startsWith(w)) s += 6;
      else if (t.includes(w)) s += 4;
      else if (r.includes(w)) s += 2;
      else return 0;
    }
    return s;
  };
  const out: CosmosHit[] = [];
  for (const g of COSMOS_GALAXIES) {
    const s = score(tx(g.name, lang), [g.name.en, g.name.ru, g.id, ...g.altNames, g.morphology, tx(g.kindLabel, lang)].join(' '));
    // Larger galaxies first among equal matches (log10 stellar mass / 10 adds at most ~1.2).
    if (s) out.push({ type: 'galaxy', id: g.id, title: tx(g.name, lang), subtitle: tx(g.kindLabel, lang), score: s + 2 + Math.log10(g.stellarMassMsun ?? 1e6) / 10 });
  }
  for (const st of KNOWN_STARS) {
    const s = score(tx(st.name, lang), [st.name.en, st.name.ru, ...st.designations, st.spectralType ?? ''].join(' '));
    if (s) out.push({ type: 'star', id: st.id, title: tx(st.name, lang), subtitle: st.spectralType ?? st.designations[0] ?? '', score: s + (st.vMag !== undefined && st.vMag < 2 ? 1 : 0) });
  }
  return out.sort((a, b) => b.score - a.score || a.title.localeCompare(b.title)).slice(0, limit);
}

// ---- Gaia overlay (separate file, ~570 kB) ----------------------------------------------------------------------

export interface GaiaOverlay {
  schema: 'aixenix.cosmos.gaia_overlay/1';
  provenance: 'observed';
  title: LocalizedText;
  selection: string;
  limits: LocalizedText;
  frame: string;
  sources: string[];
  count: number;
  /** Rows matched to a known star (the same physical star). */
  knownMatches: number;
  /** How known_id was matched; draw a matched row once, from the known-star list. */
  dedup: LocalizedText;
  /** One star per row: [source_id, raDeg, decDeg, parallaxMas, parallaxErrMas, gMag, bpRp, ruwe, xPc, yPc, zPc, knownStarId] (null when absent). */
  columns: ['source_id', 'ra', 'dec', 'parallax', 'parallax_error', 'g', 'bp_rp', 'ruwe', 'x', 'y', 'z', 'known_id'];
  rows: [string, number, number, number, number | null, number | null, number | null, number | null, number, number, number, string | null][];
}

let gaiaPromise: Promise<GaiaOverlay> | null = null;

/** Loads data/cosmos/gaia_dr3_25pc.json once (base: import.meta.env.BASE_URL). */
export function loadGaiaOverlay(base = '/'): Promise<GaiaOverlay> {
  if (!gaiaPromise) {
    const b = base.endsWith('/') ? base : base + '/';
    gaiaPromise = fetch(b + 'data/cosmos/gaia_dr3_25pc.json').then((r) => {
      if (!r.ok) throw new Error('gaia overlay: HTTP ' + r.status);
      return r.json() as Promise<GaiaOverlay>;
    });
    gaiaPromise.catch(() => {
      gaiaPromise = null;
    });
  }
  return gaiaPromise;
}

